# chromatic number via ILP / brute - try greedy and check k-coloring
# Use backtracking for k-colorability
def kcolor(k):
    adj = {i:set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    color = [-1]*n
    def bt(i):
        if i==n: return True
        used = {color[j] for j in adj[i] if color[j]!=-1}
        for c in range(k):
            if c not in used:
                color[i]=c
                if bt(i+1): return True
                color[i]=-1
        return False
    return bt(0), color[:]

for k in [2,3,4,5]:
    ok, c = kcolor(k)
